#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> x(n);
    for (int& value : x) cin >> value;

    sort(x.begin(), x.end());

    int count = 0;
    int processed = 0;

    for (int i = 0; i < n;) {
        int value = x[i];
        int j = i;
        while (j < n && x[j] == value) ++j;

        processed += j - i;
        count = max(count, (processed + value - 1) / value);
        i = j;
    }

    cout << count;
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main()
{
    int n;
    int count = 0;
    int a = 0;
    int x[100];
    int tmp[101] = {};
    vector<int> s[101];

    cin >> n;

    for (int i = 0; i < n; i++)
    {
        cin >> x[i];
        tmp[x[i]]++;
    }

    for (int i = 0; i < n; i++)
    {
        if (tmp[x[i]] <= count)
        {
            for (int j = 0; j < tmp[x[i]]; j++)
                s[j].push_back(x[i]);

            a += tmp[x[i]];
        }

        if (tmp[x[i]] > count)
        {
            if (count * x[i] - a >= tmp[x[i]])
            {
                int q = 0;

                for (int j = 0; j < tmp[x[i]]; j++)
                {
                    if (s[q].size() < static_cast<size_t>(x[i]))
                    {
                        s[q].push_back(x[i]);
                    }
                    else
                    {
                        q++;
                        j--;
                    }
                }
            }
            else
            {
                int w = tmp[x[i]] - (count * x[i] - a);

                for (int j = 0; j < count; j++)
                    while (s[j].size() < static_cast<size_t>(x[i]))
                        s[j].push_back(x[i]);

                while (w > 0)
                {
                    count++;

                    for (int j = 0; j <= x[i] && w > 0; j++)
                    {
                        s[count].push_back(x[i]);
                        w--;
                    }
                }
            }

            a += tmp[x[i]];
        }
    }

    cout << count;

    return 0;
}

